const q = ($input.first().json.query) || {};
const clean = s => String(s || '').slice(0, 3000);
const to = clean(q.to).replace(/[^a-zA-Z0-9@._+-]/g, '');
const cc = clean(q.cc).replace(/[^a-zA-Z0-9@._+-]/g, '');
const subject = clean(q.s);
const body = clean(q.b);
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
let mailto = 'mailto:' + to;
const p = [];
if (cc) p.push('cc=' + cc);
if (subject) p.push('subject=' + encodeURIComponent(subject));
if (body) p.push('body=' + encodeURIComponent(body));
if (p.length) mailto += '?' + p.join('&');
const html = '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Email fournisseur</title>'
 + '<style>body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;margin:0;padding:24px;background:#f5f6f8;color:#1a1a1a}a.b{display:block;background:#0a7cff;color:#fff;text-decoration:none;padding:16px;border-radius:12px;text-align:center;font-size:18px;font-weight:600;margin:16px 0}pre{white-space:pre-wrap;background:#fff;padding:12px;border-radius:8px;font-size:14px}</style>'
 + '<script>window.addEventListener("load",function(){setTimeout(function(){window.location.href=' + JSON.stringify(mailto) + ';},150);});</script></head><body>'
 + '<p>Ouverture de ta messagerie...</p><a class="b" href="' + esc(mailto) + '">Ouvrir l email</a>'
 + '<p>Destinataire : ' + esc(to || '(aucun)') + (cc ? '<br>Copie : ' + esc(cc) : '') + '</p>'
 + (subject ? '<p>Objet : ' + esc(subject) + '</p>' : '')
 + (body ? '<pre>' + esc(body) + '</pre>' : '')
 + '</body></html>';
return [{ json: { html } }];
